class MemberPage extends StatefulWidget {
  const MemberPage({super.key});

  @override
  State<MemberPage> createState() => _MemberPageState();
}

class _MemberPageState extends State<MemberPage> {
  late final int _mid;
  late final String _heroTag;
  late final MemberController _userController;
  final _scrollRatio = 0.0.obs;
  PageController? _headerController;
  PageController getHeaderController() =>
      _headerController ??= PageController();

  @override
  void initState() {
    super.initState();
    _mid = int.tryParse(Get.parameters['mid']!) ?? -1;
    _heroTag = Utils.makeHeroTag(_mid);
    _userController = Get.put(
      MemberController(mid: _mid),
      tag: _heroTag,
    );
  }

  @override
  void dispose() {
    _headerController?.dispose();
    _headerController = null;
    _cacheFollowTime = null;
    _cacheMedalData = null;
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context).colorScheme;
    final coui = CouiThemeData.of(context);
    final padding = MediaQuery.viewPaddingOf(context);
    final dark = theme.brightness == Brightness.dark;
    return Obx(() {
      final easedRatio = Curves.easeOut.transform(_scrollRatio.value);
      final useLightBgIcons = easedRatio >= 0.45 && !dark;
      return AnnotatedRegion<SystemUiOverlayStyle>(
        value: SystemUiOverlayStyle(
          statusBarColor: Colors.transparent,
          statusBarBrightness:
              useLightBgIcons ? Brightness.light : Brightness.dark,
          statusBarIconBrightness:
              useLightBgIcons ? Brightness.dark : Brightness.light,
          systemStatusBarContrastEnforced: false,
        ),
        child: _buildScaffold(theme, coui, padding),
      );
    });
  }

  Widget _buildScaffold(
    ColorScheme theme,
    CouiThemeData coui,
    EdgeInsets padding,
  ) {
    return VideoDetailBackground(
      child: Material(
        type: MaterialType.transparency,
        child: Obx(
          () => switch (_userController.loadingState.value) {
            Loading() => m3eLoading,
            Success(:final response) => NotificationListener<ScrollNotification>(
              onNotification: (notification) {
                if (notification.depth == 0) {
                  final pixels = notification.metrics.pixels;
                  final next = pixels <= 0
                      ? 0.0
                      : (pixels / (kToolbarHeight * 2)).clamp(0.0, 1.0);
                  if ((next - _scrollRatio.value).abs() > 0.01) {
                    _scrollRatio.value = next;
                  }
                }
                return false;
              },
              child: ExtendedNestedScrollView(
            onlyOneScrollInBody: true,
            key: _userController.scrollKey,
            scrollBehavior: const NoOverscrollIndicator(),
            pinnedHeaderSliverHeightBuilder: () =>
                kToolbarHeight + MediaQuery.viewPaddingOf(context).top,
            headerSliverBuilder: (context, innerBoxIsScrolled) {
              if (response != null) {
                return [
                  DynamicSliverAppBar.medium(
                    elevation: 0,
                    scrolledUnderElevation: 0,
                    surfaceTintColor: Colors.transparent,
                    backgroundColor: coui.surfaceBackground,
                    actions: _actions(theme),
                    title: Text(_userController.username ?? ''),
                    flexibleSpace: Obx(
                      () => UserInfoCard(
                        isOwner:
                            _userController.mid == _userController.account.mid,
                        relation: _userController.relation.value,
                        card: response.card!,
                        images: response.images!,
                        onFollow: () => _userController.onFollow(context),
                        remark: _userController.remark.value,
                        onEditRemark: () =>
                            _userController.editRemark(context),
                        live: _userController.live,
                        silence: _userController.silence,
                        headerControllerBuilder: getHeaderController,
                        showLiveMedalWall: _showLiveMedalWall,
                        charges: _userController.charges,
                        chargeCount: _userController.chargeCount,
                        guards: _userController.guards,
                        guardCount: _userController.guardCount,
                        hasMedal: _userController.medal == 1,
                      ),
                    ),
                  ),
                ];
              }
              return [
                SliverAppBar(
                  pinned: true,
                  actions: _actions(theme),
                  title: GestureDetector(
                    onTap: _userController.onReload,
                    behavior: HitTestBehavior.opaque,
                    child: Text(_userController.username ?? ''),
                  ),
                ),
              ];
            },
            body: _userController.tab2?.isNotEmpty == true
                ? Padding(
                    padding: .only(left: padding.left, right: padding.right),
                    child: Column(
                      children: [
                        if ((_userController.tab2?.length ?? 0) > 1)
                          SizedBox(
                            height: 45,
                            child: TabBar(
                              labelPadding: .zero,
                              controller: _userController.tabController,
                              tabs: _userController.tabs,
                              onTap: _userController.onTapTab,
                              dividerHeight: 0,
                              dividerColor: Colors.transparent,
                              indicatorSize: TabBarIndicatorSize.tab,
                              indicatorPadding: const EdgeInsets.symmetric(
                                horizontal: 6,
                                vertical: 5,
                              ),
                              indicator: VideoDetailChrome.pillDecoration(
                                theme,
                                coui: coui,
                              ),
                              labelColor: coui.accent,
                              unselectedLabelColor: theme.onSurfaceVariant,
                              labelStyle: const TextStyle(
                                fontSize: 14,
                                fontWeight: FontWeight.w600,
                              ),
                              unselectedLabelStyle: const TextStyle(
                                fontSize: 14,
                                fontWeight: FontWeight.w400,
                              ),
                            ),
                          ),
                        Expanded(child: _buildBody),
                      ],
                    ),
                  )
                : scrollableError,
          ),
            ),
            Error(:final errMsg) => scrollErrorWidget(
              errMsg: errMsg,
              onReload: _userController.onReload,
            ),
          },
        ),
      ),
    );
  }

