const _snackBarDisplayDuration = Duration(seconds: 1);

class LogsPage extends StatefulWidget {
  const LogsPage({super.key});

  @override
  State<LogsPage> createState() => _LogsPageState();
}

class _LogsPageState extends State<LogsPage> {
  List<_ExpandedItem<Report>> logsContent = [];
  _ExpandedItem<_DeviceInfo>? _deviceInfo;
  late bool enableLog = Pref.enableLog;

  @override
  void initState() {
    _initDeviceInfo();
    getLog();
    super.initState();
  }

  void _initDeviceInfo() {
    if (Catcher2.instance case final c?) {
      _deviceInfo = _ExpandedItem((
        c.deviceParameters,
        c.applicationParameters,
        c.customParameters,
      ));
    }
  }

  Future<void> getLog() async {
    final logsPath = await LoggerUtils.getLogsPath();
    logsContent = (await logsPath.readAsLines()).reversed.map((i) {
      try {
        final log = Report.fromJson(jsonDecode(i));
        return _ExpandedItem(log);
      } catch (e, s) {
        return _ExpandedItem(
          Report(
            'Parse log failed: $e\n\n\n$i',
            s,
            DateTime.now(),
            const {},
            const {},
            const {},
            null,
          ),
        );
      }
    }).toList();
    if (mounted) {
      setState(() {});
    }
  }

  void copyLogs() {
    Utils.copyText(
      '```\n${logsContent.join('\n\n')}```',
      needToast: false,
    );
    if (mounted) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('复制成功'),
          duration: _snackBarDisplayDuration,
        ),
      );
    }
  }

  Future<void> clearLogs() async {
    if (await LoggerUtils.clearLogs()) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text('已清空'),
            duration: _snackBarDisplayDuration,
          ),
        );
        logsContent.clear();
        setState(() {});
      }
    }
  }

  @override
  Widget build(BuildContext context) {
    final padding = MediaQuery.viewPaddingOf(context);
    return Scaffold(
      appBar: AppBar(
        title: const Text('日志'),
        actions: [
          Builder(
            builder: (menuContext) => IconButton(
              icon: const Icon(Icons.more_vert),
              onPressed: () => showCouiMenu<void>(
                context: menuContext,
                items: [
                  if (kDebugMode)
                    CouiMenuItem<void>(
                      label: '引发错误',
                      onTap: () => Timer.periodic(
                        const Duration(milliseconds: 3500),
                        (timer) {
                          Utils.reportError('Manual', StackTrace.current);
                          if (timer.tick > 3) {
                            timer.cancel();
                            if (mounted) getLog();
                          }
                        },
                      ),
                    ),
                  CouiMenuItem<void>(
                    label: '${enableLog ? '关闭' : '开启'}日志',
                    onTap: () {
                      enableLog = !enableLog;
                      GStorage.setting.put(SettingBoxKey.enableLog, enableLog);
                      ScaffoldMessenger.of(context).showSnackBar(
                        SnackBar(
                          content: Text('已${enableLog ? '开启' : '关闭'}，重启生效'),
                          duration: _snackBarDisplayDuration,
                        ),
                      );
                    },
                  ),
                  CouiMenuItem<void>(
                    label: '复制日志',
                    onTap: copyLogs,
                  ),
                  CouiMenuItem<void>(
                    label: '错误反馈',
                    onTap: () =>
                        PageUtils.launchURL('${Constants.sourceCodeUrl}/issues'),
                  ),
                  CouiMenuItem<void>(
                    label: '清空日志',
                    isDestructive: true,
                    onTap: clearLogs,
                  ),
                ],
              ),
            ),
          ),
          const SizedBox(width: 6),
        ],
      ),
      body: logsContent.isNotEmpty || _deviceInfo != null
          ? Padding(
              padding: EdgeInsets.only(
                left: padding.left + 12,
                right: padding.right + 12,
              ),
              child: CustomScrollView(
                slivers: [
                  if (_deviceInfo != null)
                    SliverToBoxAdapter(
                      child: Padding(
                        padding: const .only(bottom: 12),
                        child: _InfoCard(info: _deviceInfo!),
                      ),
                    ),
                  SliverPadding(
                    padding: EdgeInsets.only(bottom: padding.bottom + 100),
                    sliver: SliverList.separated(
                      itemCount: logsContent.length,
                      itemBuilder: (context, index) =>
                          _ReportCard(report: logsContent[index]),
                      separatorBuilder: (_, _) => const SizedBox(height: 12),
                    ),
                  ),
                ],
              ),
            )
          : scrollableError,
    );
  }
}

