                      return '用户ID要求至少为30个字符长度的纯字符串';
                    }
                    return null;
                  },
                ),
                actions: [
                  TextButton(
                    onPressed: () {
                      Get.back();
                      _userId = Digest(
                        List.generate(16, (_) => Utils.random.nextInt(256)),
                      ).toString();
                      setting.put(SettingBoxKey.blockUserID, _userId);
                      (context as Element).markNeedsBuild();
                    },
                    child: const Text('随机'),
