                autofocus: true,
              ),
              actions: [
                TextButton(
                  onPressed: () {
                    Get.back();
                    _blockServer = HttpString.sponsorBlockBaseUrl;
                    setting.put(SettingBoxKey.blockServer, _blockServer);
                    AccountManager.blockServer = _blockServer;
                    (context as Element).markNeedsBuild();
