                    _blockServer = _textController.text;
                    setting.put(SettingBoxKey.blockServer, _blockServer);
                    AccountManager.blockServer = _blockServer;
                    _checkServerStatus();
                    _getUserInfo();
                    (context as Element).markNeedsBuild();
                  },
                  child: const Text('确定'),
                ),
              ],
            ),
          );
        },
        title: Text(
          '服务器地址',
          style: titleStyle,
        ),
        subtitle: Text(
          _blockServer,
          style: subTitleStyle,
        ),
