class ReplyItemGrpc extends StatelessWidget {
  const ReplyItemGrpc({
    super.key,
    required this.replyItem,
    required this.replyLevel,
    this.replyReply,
    this.needDivider = true,
    this.onReply,
    this.onDelete,
    this.upMid,
    this.showDialogue,
    this.getTag,
    this.onViewImage,
    this.onCheckReply,
    this.onToggleTop,
    this.jumpToDialogue,
    this.youtubeStyle = false,
  });
  final ReplyInfo replyItem;
  final int replyLevel;
  final Function(ReplyInfo replyItem, int? rpid)? replyReply;
  final bool needDivider;
  final ValueChanged<ReplyInfo>? onReply;
  final Function(ReplyInfo replyItem, int? subIndex)? onDelete;
  final Int64? upMid;
  final VoidCallback? showDialogue;
  final Function? getTag;
  final VoidCallback? onViewImage;
  final ValueChanged<ReplyInfo>? onCheckReply;
  final ValueChanged<ReplyInfo>? onToggleTop;
  final VoidCallback? jumpToDialogue;
  final bool youtubeStyle;

  static final _voteRegExp = RegExp(r"^\{vote:\d+?\}$");
  static final _timeRegExp = RegExp(r'^(?:\d+[:：])?\d+[:：]\d+$');
  static bool enableWordRe = Pref.enableWordRe;
  static int? replyLengthLimit = Pref.replyLengthLimit;

  static String _locationSuffix(ReplyControl control) {
    if (!control.hasLocation()) return '';
    final label = replyLocationLabel(control.location);
    return label.isEmpty ? '' : ' · $label';
  }

  @override
  Widget build(BuildContext context) {
    final colorScheme = ColorScheme.of(context);

    void showMore() => showCouiBottomSheet(
      context: context,
      useSafeArea: true,
      isScrollControlled: true,
      constraints: BoxConstraints(
        maxWidth: min(640, context.mediaQueryShortestSide),
      ),
      builder: (context) {
        return morePanel(
          context: context,
          item: replyItem,
          onDelete: () => onDelete?.call(replyItem, null),
          isSubReply: false,
        );
      },
    );

    final useYoutube = youtubeStyle;
    final content = _buildContent(
      context,
      colorScheme,
      youtubeHeader: useYoutube
          ? _buildYoutubeHeader(context, colorScheme)
          : null,
      useYoutube: useYoutube,
    );
    Widget child = Padding(
      padding: EdgeInsets.fromLTRB(
        useYoutube ? VideoDetailChrome.horizontalInset : 12,
        10,
        useYoutube ? VideoDetailChrome.horizontalInset : 8,
        3,
      ),
      child: useYoutube && replyLevel == 1 && replyItem.count > Int64.ZERO
          ? Stack(
              children: [
                Positioned.fill(
                  child: IgnorePointer(
                    child: CustomPaint(
                      painter: _YoutubeReplyThreadPainter(
                        CouiThemeData.of(context).dividerColor,
                      ),
                    ),
                  ),
                ),
                content,
              ],
            )
          : content,
    );
    if (needDivider && !useYoutube) {
      child = Column(
        mainAxisSize: .min,
        children: [
          child,
          Divider(
            indent: 55,
            endIndent: 15,
            height: 0.3,
            color: colorScheme.outline.withValues(alpha: 0.08),
          ),
        ],
      );
    }
    return Material(
      type: MaterialType.transparency,
      child: InkWell(
        onTap: () => replyReply?.call(replyItem, null),
        onLongPress: showMore,
        onSecondaryTap: PlatformUtils.isMobile ? null : showMore,
        child: child,
      ),
    );
  }

