      mainAxisSize: .min,
      crossAxisAlignment: .start,
      children: [
        youtubeHeader ?? _buildHeader(context, colorScheme),
        SizedBox(height: useYoutube ? 6 : 10),
        if (replyControl.hasVoteOption())
          Padding(
            padding: padding,
            child: _buildVoteOption(colorScheme, replyControl.voteOption),
          ),
        Padding(
          padding: padding,
          child: TextMore.rich(
            primary: colorScheme.primary,
            style: useYoutube
                ? const TextStyle(height: 1.65, fontSize: 14.5)
                : const TextStyle(height: 1.75, fontSize: 14),
            maxLines: replyLevel == 1 ? replyLengthLimit : null,
            TextSpan(
              children: [
                if (replyControl.isUpTop) ...[
                  const WidgetSpan(
                    alignment: .middle,
                    child: PBadge(
                      text: 'TOP',
                      size: .small,
                      isStack: false,
                      type: .line_primary,
                      fontSize: 9,
                      textScaleFactor: 1,
                    ),
                  ),
                  const TextSpan(text: ' '),
                ],
                _buildMessage(
                  context,
                  colorScheme,
                  replyControl.showTranslation
                      ? replyItem.translatedContent
                      : replyItem.content,
                  replyControl,
                ),
              ],
            ),
          ),
        ),
        if (replyItem.content.pictures.isNotEmpty) ...[
          Padding(
            padding: padding,
            child: ImageGridView(
              picArr: replyItem.content.pictures
                  .map(
                    (item) => ImageModel(
                      width: item.imgWidth,
                      height: item.imgHeight,
                      url: item.imgSrc,
