        if (replyLevel != 0) ...[
          const SizedBox(height: 4),
          useYoutube
              ? _youtubeActions(context, colorScheme, replyControl)
              : buttonAction(context, colorScheme, replyControl),
        ],
        if (useYoutube)
          _youtubeBottomRow(colorScheme)
