                                size: .small,
                                isStack: false,
                                fontSize: 9,
                                textScaleFactor: 1,
                              ),
                            ),
                            const TextSpan(text: ' '),
                          ],
                          if (childReply.root == childReply.parent)
                            const TextSpan(text: ': ')
                          else if (childReply.mid != upMid)
                            const TextSpan(text: ' '),
                          _buildMessage(
                            context,
                            colorScheme,
                            childReply.content,
                            childReply.replyControl,
                          ),
                        ],
                      ),
                    ),
                  ),
                );
              }),

            if (extraRow)
              InkWell(
                onTap: () => replyReply?.call(replyItem, null),
                borderRadius: length == 1
                    ? const .all(.circular(6))
                    : const .vertical(bottom: .circular(6)),
