              ),
          ],
        ),
      ),
    );
  }

  InlineSpan _buildMessage(
    BuildContext context,
    ColorScheme colorScheme,
    Content content,
    ReplyControl replyControl,
  ) {
    final List<InlineSpan> spanChildren = <InlineSpan>[];
    bool hasNote = false;

    final urlKeys = content.urls.keys;
    // 构建正则表达式
    final List<String> specialTokens = [
      ...content.emotes.keys,
      ...content.topics.keys.map((e) => '#$e#'),
      ...content.atNameToMid.keys.map((e) => '@$e'),
      ...urlKeys,
    ];
    String patternStr = [
      ...specialTokens.map(RegExp.escape),
      r'(?:\d+[:：])?\d+[:：]\d+',
      r'\{vote:\d+?\}',
      Constants.urlRegex.pattern,
    ].join('|');
    final RegExp pattern = RegExp(patternStr);

    late List<String> matchedUrls = [];

    void addPlainTextSpan(str) {
      spanChildren.add(TextSpan(text: str));
    }

    void addUrl(String matchStr, Url url, {bool addPlainText = false}) {
      if (url.extra.isWordSearch && !enableWordRe) {
        if (addPlainText) {
          addPlainTextSpan(matchStr);
        }
        return;
      }
      final isCv = url.clickReport.startsWith('{"cvid');
      if (isCv) {
        hasNote = true;
      }
      final children = [
        if (!isCv && url.hasPrefixIcon())
          WidgetSpan(
            child: CachedNetworkImage(
              height: 19,
              memCacheHeight: 19.cacheSize(context),
              color: colorScheme.primary,
              imageUrl: ImageUtils.thumbnailUrl(url.prefixIcon),
              placeholder: (_, _) => const SizedBox.shrink(),
            ),
          ),
        TextSpan(
          text: isCv ? '[笔记] ' : url.title,
          style: TextStyle(color: colorScheme.primary),
          recognizer: NoDeadlineTapGestureRecognizer()
            ..onTap = () {
              if (url.appUrlSchema.isEmpty) {
                if (RegExp(
                  r'^(av|bv)',
                  caseSensitive: false,
                ).hasMatch(matchStr)) {
                  UrlUtils.matchUrlPush(matchStr, '');
                } else {
                  RegExpMatch? match = RegExp(
                    r'^cv(\d+)$|/read/cv(\d+)|note-app/view\?cvid=(\d+)',
                    caseSensitive: false,
                  ).firstMatch(matchStr);
                  String? cvid =
                      match?.group(1) ?? match?.group(2) ?? match?.group(3);
                  if (cvid != null) {
                    Get.toNamed(
                      '/articlePage',
                      parameters: {
                        'id': cvid,
                        'type': 'read',
                      },
                    );
                    return;
                  }
                  PageUtils.handleWebview(matchStr);
                }
              } else {
                if (url.extra.isWordSearch) {
                  Get.toNamed(
                    '/searchResult',
                    parameters: {'keyword': url.title},
                  );
                } else {
                  PageUtils.handleWebview(matchStr);
                }
              }
            },
        ),
      ];
      if (isCv) {
        spanChildren.insertAll(0, children);
      } else {
        spanChildren.addAll(children);
      }
    }

    // 分割文本并处理每个部分
    content.message.splitMapJoin(
      pattern,
      onMatch: (Match match) {
        String matchStr = match[0]!;
        late final name = matchStr.substring(1);
        late final topic = matchStr.substring1;
        if (content.emotes.containsKey(matchStr)) {
          // 处理表情
          final emote = content.emotes[matchStr]!;
          final size = emote.size.toInt() * 20.0;
          final url = emote.hasWebpUrl()
              ? emote.webpUrl
              : emote.hasGifUrl()
              ? emote.gifUrl
              : emote.url;
          spanChildren.add(
            WidgetSpan(
              child: emoteTooltipBuilder(
                url: url,
                emote: matchStr,
                triggerMode: .tap,
                jumpUrl: emote.hasJumpUrl() ? emote.jumpUrl : null,
                colorScheme: colorScheme,
                child: NetworkImgLayer(
                  src: url,
                  type: .emote,
                  width: size,
                  height: size,
                ),
              ),
            ),
          );
        } else if (matchStr.startsWith("@") &&
            content.atNameToMid.containsKey(name)) {
          // 处理@用户
          spanChildren.add(
            TextSpan(
              text: matchStr,
              style: TextStyle(color: colorScheme.primary),
              recognizer: NoDeadlineTapGestureRecognizer()
                ..onTap = () =>
                    Get.toNamed('/member?mid=${content.atNameToMid[name]}'),
            ),
          );
        } else if (_voteRegExp.hasMatch(matchStr)) {
          spanChildren.add(
            TextSpan(
              text: '投票: ${content.vote.title}',
              style: TextStyle(color: colorScheme.primary),
              recognizer: NoDeadlineTapGestureRecognizer()
                ..onTap = () =>
                    showVoteDialog(context, content.vote.id.toInt()),
            ),
          );
        } else if (_timeRegExp.hasMatch(matchStr)) {
          matchStr = matchStr.replaceAll('：', ':');
          bool isValid = false;
          final heroTag = getTag?.call() ?? Get.arguments?['heroTag'];
          if (kDebugMode) {
            debugPrint('Validating timestamp: $matchStr with tag: $heroTag');
          }
          if (heroTag != null) {
            try {
              final ctr = Get.find<AudioController>(tag: heroTag);
              isValid =
                  DurationUtils.parseDuration(matchStr) * 1000 <=
                  ctr.duration.value * 1000;
            } catch (_) {
              try {
                final ctr = Get.find<VideoDetailController>(tag: heroTag);
                isValid =
                    DurationUtils.parseDuration(matchStr) * 1000 <=
                    ctr.data.timeLength!;
              } catch (e) {
                if (kDebugMode) debugPrint('failed to validate: $e');
              }
            }
          }
          spanChildren.add(
            TextSpan(
              text: isValid ? ' $matchStr ' : matchStr,
              style: isValid ? TextStyle(color: colorScheme.primary) : null,
              recognizer: isValid
                  ? (NoDeadlineTapGestureRecognizer()
                      ..onTap = () {
                        // 跳转到指定位置
                        try {
                          final heroTag =
                              getTag?.call() ?? Get.arguments?['heroTag'];
                          final duration = Duration(
                            seconds: DurationUtils.parseDuration(matchStr),
                          );
                          SmartDialog.showToast('跳转至：$matchStr');
                          if (kDebugMode) {
                            debugPrint('Seeking to $duration with tag: $heroTag');
                          }
                          try {
                            final ctr = Get.find<AudioController>(tag: heroTag);
                            if (kDebugMode) debugPrint('Seeking AudioController');
                            ctr.seekTo(
                              duration,
                              isSeek: false,
                            );
                          } catch (_) {
                            final ctr = Get.find<VideoDetailController>(tag: heroTag);
                            if (kDebugMode) debugPrint('Seeking VideoDetailController');
                            ctr.plPlayerController.seekTo(
                              duration,
                              isSeek: false,
                            );
                          }
                        } catch (e) {
                          SmartDialog.showToast('跳转失败: $e');
                          if (kDebugMode) debugPrint('Seek error: $e');
                        }
                      })
                  : null,
            ),
          );
        } else {
          final url = content.urls[matchStr];
          if (url != null && !matchedUrls.contains(matchStr)) {
            addUrl(matchStr, url, addPlainText: true);
            // 只显示一次
            matchedUrls.add(matchStr);
          } else if (matchStr.length > 1 && content.topics[topic] != null) {
            spanChildren.add(
              TextSpan(
                text: matchStr,
                style: TextStyle(color: colorScheme.primary),
                recognizer: NoDeadlineTapGestureRecognizer()
                  ..onTap = () {
                    Get.toNamed(
                      '/searchResult',
                      parameters: {'keyword': topic},
                    );
                  },
              ),
            );
          } else if (Constants.urlRegex.hasMatch(matchStr)) {
            spanChildren.add(
              TextSpan(
                text: matchStr,
                style: TextStyle(color: colorScheme.primary),
                recognizer: NoDeadlineTapGestureRecognizer()
                  ..onTap = () => PageUtils.handleWebview(matchStr),
              ),
            );
          } else {
            addPlainTextSpan(matchStr);
          }
        }
        return '';
      },
      onNonMatch: (String nonMatchStr) {
        addPlainTextSpan(nonMatchStr);
        return nonMatchStr;
      },
    );

    if (!hasNote && replyControl.isNote && replyControl.isNoteV2) {
      final Color color;
      NoDeadlineTapGestureRecognizer? recognizer;

      final hasClickUrl = content.richText.note.hasClickUrl();
      if (hasClickUrl || content.richText.opus.hasOpusId()) {
        color = colorScheme.primary;
        recognizer = NoDeadlineTapGestureRecognizer()
          ..onTap = () => hasClickUrl
              ? PiliScheme.routePushFromUrl(content.richText.note.clickUrl)
              : Get.toNamed(
                  '/articlePage',
                  parameters: {
                    'id': content.richText.opus.opusId.toString(),
                    'type': 'opus',
                  },
                );
      } else {
        color = colorScheme.secondary;
      }
      spanChildren.insert(
        0,
        TextSpan(
          text: '[笔记] ',
          style: TextStyle(color: color),
          recognizer: recognizer,
        ),
      );
    }

    return TextSpan(children: spanChildren);
  }

  Future<void> _confirmAndDeleteReply(
    BuildContext context,
    ReplyInfo item,
    Int64 ownerMid,
    VoidCallback onDelete,
  ) async {
    final message = item.content.message;
    final bool? isDelete = await showDialog<bool>(
      context: context,
      builder: (context) {
        final colorScheme = ColorScheme.of(context);
        return AlertDialog(
          title: const Text('删除评论'),
          content: Text.rich(
            TextSpan(
              children: [
                const TextSpan(text: '确定删除这条评论吗？\n\n'),
                if (ownerMid != item.member.mid.toInt()) ...[
                  TextSpan(
                    text: '@${item.member.name}',
                    style: TextStyle(
                      color: colorScheme.primary,
                    ),
                  ),
                  const TextSpan(text: ':\n'),
                ],
                TextSpan(text: message),
              ],
            ),
          ),
          actions: [
            TextButton(
              onPressed: () => Get.back(result: false),
              child: Text(
                '取消',
                style: TextStyle(
                  color: colorScheme.outline,
                ),
              ),
            ),
            TextButton(
              onPressed: () => Get.back(result: true),
              child: const Text('确定'),
            ),
          ],
        );
      },
    );
    if (isDelete == null || !isDelete) {
      return;
    }
    SmartDialog.showLoading(msg: '删除中...');
    final res = await VideoHttp.replyDel(
      type: item.type.toInt(),
      oid: item.oid.toInt(),
      rpid: item.id.toInt(),
    );
    SmartDialog.dismiss();
    if (res.isSuccess) {
      SmartDialog.showToast('删除成功');
      onDelete();
    } else {
      SmartDialog.showToast('删除失败, $res');
    }
  }

  void _reportReply(
    BuildContext context,
    ColorScheme colorScheme,
    ReplyInfo item,
    VoidCallback onDelete,
  ) {
    final oid = item.oid;
    final rpid = item.id;
    autoWrapReportDialog(
      context,
      onRemove: onDelete,
      mid: () => item.mid.toInt(),
      ReportOptions.commentReport,
      withContent: ReportOptions.withContentReply,
      contentRequired: ReportOptions.contentRequiredReply,
      reportUrl:
          'https://www.bilibili.com/h5/comment/report?oid=$oid&pageType=${item.type}&rpid=$rpid&platform=android&build=8430300&${ThemeUtils.themeUrl(colorScheme.isDark)}',
      (reasonType, reasonDesc, banUid) async {
        final res = await ReplyHttp.report(
          rpid: rpid,
          oid: oid,
          reasonType: reasonType,
          reasonDesc: reasonDesc,
          banUid: banUid,
        );
        if (res.isSuccess) {
          onDelete();
        }
        return res;
      },
    );
  }

  void _blockReplyUser(ReplyInfo item) {
    final mid = item.member.mid.toInt();
    final rawName = item.member.name.trim();
    final name = rawName.isEmpty ? 'UID:$mid' : rawName;
    final mids = Map<int, String>.from(Pref.replyBlockedMids);
    mids[mid] = name;
    Pref.replyBlockedMids = mids;
    ReplyGrpc.replyBlockedMids = mids;
    SmartDialog.showToast('已屏蔽 $name');
  }

