const _kMaxExtent = 625.0;
const _kConstraints = BoxConstraints(maxWidth: _kMaxExtent);

class WhisperDetailPage extends CommonRichTextPubPage {
  const WhisperDetailPage({
    super.key,
    super.autofocus = false,
  });

  @override
  State<WhisperDetailPage> createState() => _WhisperDetailPageState();
}

class _WhisperDetailPageState
    extends CommonRichTextPubPageState<WhisperDetailPage> {
  final _whisperDetailController = Get.put(
    WhisperDetailController(),
    tag: Utils.makeHeroTag(Get.parameters['talkerId']),
  );

  @override
  Widget build(BuildContext context) {
    final padding = MediaQuery.viewPaddingOf(context);
    late final containerColor = ElevationOverlay.colorWithOverlay(
      theme.colorScheme.surface,
      theme.hoverColor,
      1,
    );
    return SimpleScaffold(
      appBar: AppBar(
        title: GestureDetector(
          behavior: HitTestBehavior.opaque,
          onTap: () {
            if (_whisperDetailController.mid != null) {
              feedBack();
              Get.toNamed('/member?mid=${_whisperDetailController.mid}');
            }
          },
          child: Row(
            mainAxisSize: MainAxisSize.min,
            children: [
              NetworkImgLayer(
                width: 34,
                height: 34,
                type: ImageType.avatar,
                src: _whisperDetailController.face,
              ),
              const SizedBox(width: 6),
              Flexible(
                child: Text(
                  _whisperDetailController.name,
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                  style: const TextStyle(height: 1, fontSize: 16),
                  strutStyle: const StrutStyle(
                    leading: 0,
                    height: 1,
                    fontSize: 16,
                  ),
                ),
              ),
              if (_whisperDetailController.isLive) ...[
                const SizedBox(width: 10),
                Image.asset(
                  Assets.livingRect,
                  height: 16,
                  cacheHeight: 16.cacheSize(context),
                  filterQuality: FilterQuality.low,
                ),
              ],
            ],
          ),
        ),
        actions: [
          IconButton(
            tooltip: '设置',
            onPressed: () => Get.to(
              WhisperLinkSettingPage(
                talkerUid: _whisperDetailController.talkerId,
              ),
            ),
            icon: Icon(
              size: 22,
              Icons.settings,
              color: theme.colorScheme.onSurfaceVariant.withValues(alpha: 0.8),
            ),
          ),
          const SizedBox(width: 5),
        ],
      ),
      body: Padding(
        padding: EdgeInsets.only(left: padding.left, right: padding.right),
        child: Column(
          children: [
            Expanded(
              child: Listener(
                onPointerDown: hidePanel,
                behavior: .opaque,
                child: Obx(
                  () => _buildBody(_whisperDetailController.loadingState.value),
                ),
              ),
            ),
            if (_whisperDetailController.mid != null) ...[
              ConstrainedBox(
                constraints: _kConstraints,
                child: _buildInputView(containerColor),
              ),
              ConstrainedBox(
                constraints: _kConstraints,
                child: buildPanelContainer(containerColor),
              ),
            ] else
              SizedBox(height: padding.bottom),
          ],
        ),
      ),
    );
  }

  Widget _buildBody(LoadingState<List<Msg>?> loadingState) {
    return switch (loadingState) {
      Loading() => m3eLoading,
      Success(:final response) =>
        response != null && response.isNotEmpty
            ? ChatListView.separated(
                maxExtent: _kMaxExtent,
                itemCount: response.length,
                padding: const .all(kChatListPadding),
                physics: platformAlwaysClampingPhysics,
                controller: _whisperDetailController.scrollController,
                itemBuilder: (context, int index) {
                  if (index == response.length - 1) {
                    _whisperDetailController.onLoadMore();
                  }
                  final item = response[index];
                  final isOwner =
                      item.senderUid.toInt() ==
                      _whisperDetailController.account.mid;
                  return ChatItem(
                    item: item,
                    eInfos: _whisperDetailController.eInfos,
                    onLongPress: () => onLongPress(index, item, isOwner),
                    onSecondaryTapUp: PlatformUtils.isDesktop
                        ? (e) =>
                              _showMenu(e.globalPosition, index, item, isOwner)
                        : null,
                    isOwner: isOwner,
                  );
                },
                separatorBuilder: (context, index) =>
                    const SizedBox(height: 12),
              )
            : scrollErrorWidget(onReload: _whisperDetailController.onReload),
      Error(:final errMsg) => scrollErrorWidget(
        errMsg: errMsg,
        onReload: _whisperDetailController.onReload,
      ),
    };
  }

  void _showMenu(Offset offset, int index, Msg item, bool isOwner) {
    showCouiMenu<void>(
      context: context,
      offset: offset,
      items: [
        if (isOwner)
          CouiMenuItem<void>(
            label: '撤回',
            onTap: () => _whisperDetailController.sendMsg(
              message: '${item.msgKey}',
              onClearText: editController.clear,
              msgType: .EN_MSG_TYPE_DRAW_BACK,
              index: index,
            ),
          )
        else
          CouiMenuItem<void>(
            label: '举报',
            isDestructive: true,
            onTap: () => onReport(item),
          ),
      ],
    );
  }

  void onReport(Msg item) {
    autoWrapReportDialog(
      context,
      ReportOptions.imMsgReport,
      (reasonType, reasonDesc, banUid) => _whisperDetailController.onReport(
        item,
        reasonType,
        reasonDesc ?? ReportOptions.imMsgReport['']![reasonType]!,
      ),
    );
  }

  void onLongPress(int index, Msg item, bool isOwner) {
    Feedback.forLongPress(context);
    showDialog(
      context: context,
      builder: (context) => AlertDialog(
        clipBehavior: Clip.hardEdge,
        contentPadding: const EdgeInsets.symmetric(vertical: 12),
        content: isOwner
            ? ListTile(
                onTap: () {
                  Get.back();
                  _whisperDetailController.sendMsg(
                    message: '${item.msgKey}',
                    onClearText: editController.clear,
                    msgType: .EN_MSG_TYPE_DRAW_BACK,
                    index: index,
                  );
                },
                dense: true,
                title: const Text('撤回', style: TextStyle(fontSize: 14)),
              )
            : ListTile(
                onTap: () {
                  Get.back();
                  onReport(item);
                },
                dense: true,
                title: const Text('举报', style: TextStyle(fontSize: 14)),
              ),
      ),
    );
  }

  Widget _buildInputView(Color containerColor) {
    return Container(
      padding: const EdgeInsets.symmetric(vertical: 8),
      decoration: BoxDecoration(
        color: containerColor,
        borderRadius: const BorderRadius.vertical(top: Radius.circular(16)),
      ),
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.end,
        children: [
          IconButton(
            onPressed: () =>
                updatePanelType(panelType.value == .emoji ? .keyboard : .emoji),
            icon: const Icon(Icons.emoji_emotions),
            tooltip: '表情',
          ),
          Expanded(
            child: RichTextField(
              key: key,
              focusNode: focusNode,
              controller: editController,
              minLines: 1,
              maxLines: 4,
              onChanged: onChanged,
              onSubmitted: onSubmitted,
              textInputAction: TextInputAction.newline,
              decoration: InputDecoration(
                filled: true,
                hintText: '发个消息聊聊呗~',
                fillColor: CouiThemeData.of(context).inputFillColor,
                border: OutlineInputBorder(
                  borderSide: BorderSide(
                    color: CouiThemeData.of(context).inputBorderColor,
                    width: 0.75,
                  ),
                  borderRadius: Coui.imageRadius,
                  gapPadding: 0,
                ),
                enabledBorder: OutlineInputBorder(
                  borderSide: BorderSide(
                    color: CouiThemeData.of(context).inputBorderColor,
                    width: 0.75,
                  ),
                  borderRadius: Coui.imageRadius,
                  gapPadding: 0,
                ),
                contentPadding: const EdgeInsets.all(10),
              ),
              // inputFormatters: [LengthLimitingTextInputFormatter(500)],
            ),
          ),
          Obx(
            () {
              final enablePublish = this.enablePublish.value;
              return IconButton(
                onPressed: () async {
                  if (enablePublish) {
                    _whisperDetailController.sendMsg(
                      message: editController.rawText,
                      onClearText: () {
                        editController.clear();
                        this.enablePublish.value = false;
                      },
                    );
                  } else {
                    try {
                      final pickedFile = await imagePicker.pickImage(
                        source: ImageSource.gallery,
                        imageQuality: 100,
                        requestFullMetadata: false,
                      );
                      if (pickedFile != null) {
                        final path = pickedFile.path;
                        SmartDialog.showLoading(msg: '正在上传图片');
                        final result = await MsgHttp.uploadBfs(
                          path: path,
                          biz: 'im',
                        );
                        if (result case Success(:final response)) {
                          final mimeType =
                              lookupMimeType(
                                path,
                              )?.split('/').elementAtOrNull(1) ??
                              'jpg';
                          final picMsg = {
                            'url': response.imageUrl,
                            'height': response.imageHeight,
                            'width': response.imageWidth,
                            'imageType': mimeType,
                            'original': 1,
                            'size': response.imgSize,
                          };
                          SmartDialog.showLoading(msg: '正在发送');
                          await _whisperDetailController
                              .sendMsg(
                                picMsg: picMsg,
                                onClearText: editController.clear,
                              )
                              .whenComplete(() {
                                if (PlatformUtils.isMobile) {
                                  File(path).tryDel();
                                }
                              });
                        } else {
                          SmartDialog.dismiss();
                          result.toast();
                          return;
                        }
                      }
                    } catch (e) {
                      SmartDialog.showToast(e.toString());
                    }
                  }
                },
                icon: Icon(
                  enablePublish
                      ? Icons.send
                      : Icons.add_photo_alternate_outlined,
                ),
                tooltip: enablePublish ? '发送' : '图片',
              );
            },
          ),
        ],
      ),
    );
  }

  @override
  Widget? get customPanel => EmotePanel(onChoose: onChooseEmote);

  @override
  Future<void> onCustomPublish({List? pictures}) {
    throw UnimplementedError();
  }

  @override
  Future<void>? onMention([bool fromClick = false]) => null;

  @override
  void onSave() {}
}

import 'package:PiliPlus/common/skeleton/whisper_item.dart';
import 'package:PiliPlus/common/sliver_single_child_delegate.dart';
import 'package:PiliPlus/common/widgets/coui_menu.dart';
import 'package:PiliPlus/common/widgets/flutter/refresh_indicator.dart';
import 'package:PiliPlus/common/widgets/loading_widget/http_error.dart';
import 'package:PiliPlus/common/widgets/scaffold/simple_scaffold.dart';
import 'package:PiliPlus/grpc/bilibili/app/im/v1.pb.dart';
import 'package:PiliPlus/http/loading_state.dart';
import 'package:PiliPlus/pages/whisper/widgets/item.dart';
import 'package:PiliPlus/pages/whisper_secondary/controller.dart';
import 'package:PiliPlus/utils/extension/three_dot_ext.dart';
import 'package:get/get.dart';
import 'package:material_ui/material_ui.dart';

class WhisperSecPage extends StatefulWidget {
  const WhisperSecPage({
    super.key,
    required this.name,
    required this.sessionPageType,
  });

  final String name;
  final SessionPageType sessionPageType;

  @override
  State<WhisperSecPage> createState() => _WhisperSecPageState();
}

class _WhisperSecPageState extends State<WhisperSecPage> {
  late final WhisperSecController _controller;

  @override
  void initState() {
    super.initState();
    _controller = Get.put(
      WhisperSecController(sessionPageType: widget.sessionPageType),
      tag: widget.sessionPageType.name,
    );
  }

  @override
  Widget build(BuildContext context) {
    return SimpleScaffold(
      appBar: AppBar(
        title: Text(widget.name),
        actions: [
          Obx(() {
            final threeDotItems = _controller.threeDotItems.value;
            if (threeDotItems != null && threeDotItems.isNotEmpty) {
              return Builder(
                builder: (menuContext) => IconButton(
                  icon: const Icon(Icons.more_vert),
                  onPressed: () => showCouiMenu(
                    context: menuContext,
                    items: threeDotItems
                        .map(
                          (e) => CouiMenuItem(
                            label: e.title ?? '',
                            leading: e.type.icon,
                            onTap: () => e.type.action(
                              context: context,
                              controller: _controller,
                              item: e,
                            ),
                          ),
                        )
                        .toList(),
                  ),
                ),
              );
            }
            return const SizedBox.shrink();
          }),
        ],
      ),
      body: refreshIndicator(
        onRefresh: _controller.onRefresh,
        child: CustomScrollView(
          physics: const AlwaysScrollableScrollPhysics(),
          slivers: [
            SliverPadding(
              padding: EdgeInsets.only(
                bottom: MediaQuery.viewPaddingOf(context).bottom + 100,
              ),
              sliver: Obx(() => _buildBody(_controller.loadingState.value)),
            ),
          ],
        ),
      ),
    );
  }

  Widget _buildBody(LoadingState<List<Session>?> loadingState) {
    switch (loadingState) {
      case Loading():
        return const SliverPrototypeExtentList(
          prototypeItem: WhisperItemSkeleton(),
          delegate: SliverSingleChildDelegate(
            count: 12,
            child: WhisperItemSkeleton(),
          ),
        );
      case Success(:final response):
        if (response != null && response.isNotEmpty) {
          final divider = Divider(
            indent: 72,
            endIndent: 20,
            height: 0,
            color: Colors.grey.withValues(alpha: 0.1),
          );
          return SliverList.separated(
            itemCount: response.length,
            itemBuilder: (context, index) {
              if (index == response.length - 1) {
                _controller.onLoadMore();
              }
              final item = response[index];
              return WhisperSessionItem(
                item: item,
                onSetTop: (isTop, talkerId) =>
                    _controller.onSetTop(item, index, isTop, talkerId),
                onSetMute: (isMuted, talkerUid) =>
                    _controller.onSetMute(item, isMuted, talkerUid),
                onRemove: (talkerId) => _controller.onRemove(index, talkerId),
              );
            },
            separatorBuilder: (context, index) => divider,
          );
        }
        return HttpError(onReload: _controller.onReload);
      case Error(:final errMsg):
        return HttpError(
          errMsg: errMsg,
          onReload: _controller.onReload,
        );
    }
  }
}

import 'package:PiliPlus/common/widgets/coui_glass_surface.dart';
import 'package:PiliPlus/models/common/reply/reply_sort_type.dart';
import 'package:PiliPlus/pages/video/reply/widgets/youtube_comment_chrome.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:material_ui/material_ui.dart';

void main() {
  testWidgets('sort buttons send the requested sort', (tester) async {
    ReplySortType? selected;
    await tester.pumpWidget(MaterialApp(
      home: Scaffold(
        body: YoutubeCommentSort(
          selected: ReplySortType.hot,
          totalCount: 128,
          onSelect: (value) => selected = value,
        ),
      ),
    ));
    expect(find.text('全部评论'), findsOneWidget);
    expect(find.text('128'), findsOneWidget);
    await tester.tap(find.text('最热门'));
    await tester.pump();
    await tester.pump(const Duration(milliseconds: 400));
    await tester.tap(find.text('最新'));
    await tester.pump();
    await tester.pump(const Duration(milliseconds: 300));
    expect(selected, ReplySortType.time);
  });

  testWidgets('curated-only sorting is not falsely switchable', (tester) async {
    var calls = 0;
    await tester.pumpWidget(MaterialApp(
      home: Scaffold(
        body: YoutubeCommentSort(
          selected: ReplySortType.select,
          onSelect: (_) => calls++,
        ),
      ),
    ));
    expect(find.text('精选评论'), findsOneWidget);
    expect(find.text('最热门'), findsNothing);
    expect(find.text('最新'), findsNothing);
    await tester.tap(find.text('精选评论'), warnIfMissed: false);
    expect(calls, 0);
  });

  testWidgets('composer opens reply flow with safe area reserved', (tester) async {
    var taps = 0;
    await tester.pumpWidget(MaterialApp(
      home: Scaffold(
        body: Align(
          alignment: Alignment.topCenter,
          child: YoutubeCommentComposer(
            bottomPadding: 24,
            onTap: () => taps++,
          ),
        ),
      ),
    ));
    expect(find.byType(CouiGlassSurface), findsOneWidget);
    expect(find.byIcon(Icons.edit_outlined), findsOneWidget);
    await tester.tap(find.text('写评论…'));
    expect(taps, 1);
    // 8 (top) + 56 (capsule) + 8 (bottom) + 24 (bottomPadding) = 96
    expect(tester.getSize(find.byType(YoutubeCommentComposer)).height, 96);
  });
}
